#!/usr/bin/env python3
"""Minimal Android boot image (header v0/v1/v2) unpacker + ikconfig/vmlinux extraction."""
import struct, sys, os, gzip, io, subprocess

def rd(f, off, n):
    f.seek(off)
    return f.read(n)

def unpack(path, outdir):
    os.makedirs(outdir, exist_ok=True)
    size = os.path.getsize(path)
    with open(path, 'rb') as f:
        hdr = rd(f, 0, 1632)
    magic = hdr[:8]
    print(f"file={path} size={size} magic={magic!r}")
    if magic != b'ANDROID!':
        print("not ANDROID! (may be Samsung zImage-only or different format)")
        return None
    (ksize, kaddr, rsize, raddr, ssize, saddr, tags, page,
     field9, osver) = struct.unpack_from('<10I', hdr, 8)
    name = hdr[48:64].split(b'\0')[0]
    cmdline = hdr[64:576].split(b'\0')[0]
    extra = hdr[592:1616].split(b'\0')[0]
    hv = field9 if field9 in (0, 1, 2) else 0
    dt_size = field9 if hv == 0 else 0
    print(f"kernel={ksize} ramdisk={rsize} second={ssize} dt={dt_size} page={page} hdrver={hv}")
    print(f"name={name!r}\ncmdline={cmdline.decode('utf-8','replace')}\nextra={extra.decode('utf-8','replace')}")
    if page == 0 or page > 65536:
        print("bad page size"); return None
    pos = page
    def take(n, nm):
        nonlocal pos
        if n == 0:
            print(f"{nm}: empty"); return b''
        data = rd(f, pos, n)
        padded = (n + page - 1) // page * page
        pos += padded
        print(f"{nm}: off={pos-padded} len={n} -> {nm}.bin")
        open(os.path.join(outdir, nm + '.bin'), 'wb').write(data)
        return data
    kern = take(ksize, 'kernel')
    take(rsize, 'ramdisk')
    take(ssize, 'second')
    if hv == 0 and dt_size:
        take(dt_size, 'dt')
    elif hv >= 1:
        # v1: recovery_dtbo_size, recovery_dtbo_offset, header_size ; v2 adds dtb_size, dtb_addr
        hdr2 = rd(f, 1632, 16)
        rd_size, rd_off = struct.unpack_from('<II', hdr2, 0)
        print(f"recovery_dtbo size={rd_size} off={rd_off}")
        if hv == 2:
            (dtb_size, dtb_addr) = struct.unpack_from('<IQ', rd(f, 1648, 12), 0)
            print(f"dtb size={dtb_size} addr={dtb_addr:#x}")
    return {'kernel': kern, 'page': page}

MAGICS = [
    (b'\x1f\x8b\x08', 'gzip'),
    (b'\xfd7zXZ\x00', 'xz'),
    (b'\x04\x22\x4d\x18', 'lz4'),
    (b'\x28\xb5\x2f\xfd', 'zstd'),
    (b'\x89LZO\x00\r\n\x1a\n', 'lzo'),
    (b'\x5d\x00\x00', 'lzma'),
]

def decompress_any(data, nm, outdir):
    for magic, kind in MAGICS:
        i = data.find(magic)
        while i != -1:
            try:
                if kind == 'gzip':
                    out = gzip.decompress(data[i:])
                elif kind == 'xz':
                    import lzma; out = lzma.decompress(data[i:])
                elif kind == 'zstd':
                    out = subprocess.run(['zstd','-d','-c'], input=data[i:], capture_output=True).stdout
                elif kind == 'lz4':
                    out = subprocess.run(['lz4','-d','-c'], input=data[i:], capture_output=True).stdout
                else:
                    out = b''
                if len(out) > 1024*1024:
                    p = os.path.join(outdir, f'{nm}.{kind}')
                    open(p,'wb').write(out)
                    print(f"decompressed {kind} at off {i}: {len(out)} bytes -> {p}")
                    return out
            except Exception as e:
                pass
            i = data.find(magic, i+1)
    return None

def extract_ikconfig(kern, outdir):
    st = kern.find(b'IKCFG_ST')
    ed = kern.find(b'IKCFG_ED', st if st != -1 else 0)
    print(f"IKCFG_ST={st} IKCFG_ED={ed}")
    if st != -1 and ed > st:
        blob = kern[st+8:ed]
        for kind, fn in (('gzip', lambda b: gzip.decompress(b)),
                         ('xz', lambda b: __import__('lzma').decompress(b)),
                         ('lz4', lambda b: subprocess.run(['lz4','-d','-c'], input=b, capture_output=True).stdout)):
            try:
                cfg = fn(blob)
                if b'CONFIG_' in cfg:
                    p = os.path.join(outdir, 'config')
                    open(p,'wb').write(cfg)
                    print(f"ikconfig {kind} -> {p} ({len(cfg)} bytes)")
                    return cfg
            except Exception as e:
                print(f"ikconfig {kind} failed: {e}")
    return None

if __name__ == '__main__':
    src, outdir = sys.argv[1], sys.argv[2]
    r = unpack(src, outdir)
    if r:
        kern = r['kernel']
        extract_ikconfig(kern, outdir)
        decompress_any(kern, 'vmlinux', outdir)

#!/usr/bin/env python3
"""Compare a ROM kernel .config against an upstream kernel tree.

Builds:
  - set of config symbols declared in upstream Kconfig files
  - map config symbol -> object paths from upstream Makefiles
Then reports every enabled ROM symbol with upstream status and candidate paths.
"""
import os, re, sys, csv, json

KCONF_RE = re.compile(r'^\s*(?:menu)?config\s+([A-Za-z0-9_]+)\s*$')
OBJ_RE = re.compile(r'obj-\$\((CONFIG_[A-Za-z0-9_]+)\)\s*[:+]?=\s*(.+)$')
CFG_RE = re.compile(r'^(CONFIG_[A-Za-z0-9_]+)=(.*)$')

def parse_config(path):
    cfg = {}
    for line in open(path, errors='replace'):
        m = CFG_RE.match(line.strip())
        if m:
            cfg[m.group(1)] = m.group(2).strip().strip('"')
    return cfg

def scan_upstream(root):
    syms = set()
    sym2paths = {}
    for dirpath, dirnames, filenames in os.walk(root):
        dirnames[:] = [d for d in dirnames if d not in ('.git',)]
        for fn in filenames:
            p = os.path.join(dirpath, fn)
            rel = os.path.relpath(p, root)
            if fn == 'Kconfig' or fn.startswith('Kconfig.'):
                try:
                    for line in open(p, errors='replace'):
                        m = KCONF_RE.match(line)
                        if m:
                            syms.add(m.group(1))
                except OSError:
                    pass
            elif fn == 'Makefile':
                try:
                    for line in open(p, errors='replace'):
                        m = OBJ_RE.search(line)
                        if m:
                            sym2paths.setdefault(m.group(1), []).append(rel)
                except OSError:
                    pass
    return syms, sym2paths

def main():
    cfgpath, upstream, outdir = sys.argv[1], sys.argv[2], sys.argv[3]
    cfg = parse_config(cfgpath)
    print(f"ROM config symbols: {len(cfg)}")
    usyms, upaths = scan_upstream(upstream)
    print(f"upstream Kconfig symbols: {len(usyms)}")
    rows = []
    for sym, val in sorted(cfg.items()):
        if val == 'n':
            continue
        rows.append({
            'symbol': sym,
            'value': val,
            'upstream_symbol': 'yes' if sym in usyms else 'NO',
            'upstream_paths': ';'.join(sorted(set(upaths.get(sym, []))))[:400],
        })
    os.makedirs(outdir, exist_ok=True)
    out = os.path.join(outdir, 'config_vs_upstream.csv')
    with open(out, 'w', newline='') as f:
        w = csv.DictWriter(f, fieldnames=['symbol','value','upstream_symbol','upstream_paths'])
        w.writeheader(); w.writerows(rows)
    missing = [r for r in rows if r['upstream_symbol'] == 'NO']
    print(f"enabled symbols: {len(rows)}; not declared upstream: {len(missing)}")
    print(f"csv: {out}")
    print("\n--- enabled symbols absent from upstream Kconfig (first 120) ---")
    for r in missing[:120]:
        print(f"{r['symbol']}={r['value']}")

if __name__ == '__main__':
    main()

