cd /tmp && python3 - <<'EOF'
import re
def extract(path, needle):
    lines=open(path,errors='replace').read().split('\n')
    for i,l in enumerate(lines):
        if needle in l and l.rstrip().endswith('{'):
            depth=0; out=[]
            for j in range(i,len(lines)):
                out.append(lines[j])
                depth += lines[j].count('{') - lines[j].count('}')
                if depth==0: return '\n'.join(out)
    return ''
for node in ('ea8061_wxga','samsung,sec-battery','sm5703-fuelgauge','samsung,brcm-wlan','cm36672p@60','stk3013@48','k2hh-i2c@1D'):
    a=extract('nura_j7.sorted.dts',node); b=extract('rom_000_800.sorted.dts',node)
    print(f'===== {node}: nura {len(a)} bytes, rom {len(b)} bytes')
    if a!=b:
        import difflib
        d=list(difflib.unified_diff(a.split('\n'),b.split('\n'),lineterm=''))
        print('\n'.join(d[:40]))
    else:
        print('IDENTICAL')
EOF

